style.css:
/* Tumblr — Make all text white */
body,
body *,
p,
span,
div,
a,
h1,
h2,
h3,
h4,
h5,
h6,
li,
blockquote,
input,
textarea,
label,
button {
  color: #ffffff !important;
}

/* Keep links white */
a,
a:visited,
a:hover {
  color: #ffffff !important;
}

/* White text in text fields */
input,
textarea {
  -webkit-text-fill-color: #ffffff !important;
  caret-color: #ffffff !important;
}

/* Placeholder text */
input::placeholder,
textarea::placeholder {
  color: #cccccc !important;
}
